			function onCbg2SelectionChange(e) {
			    var cbg2 = e.control;
			    var cbg3 = app.lookup("cbg3");
			    
			    if (cbg2.value) {
			        var valueArr = cbg2.value.split(",");
			        
			        if (valueArr.indexOf("ALL") == valueArr.length - 1) {
			            
			            for (var idx = 1; idx < cbg2.getItemCount(); idx++) {
			                cbg2.removeSelection(idx);
			            }
			        } else
			            cbg2.removeSelectionByValue("ALL");
			    }
			    
			    cbg3.getSelection().forEach(function(item) {
			        if (!cbg3.getItemByValue(item.value))
			            cbg3.removeSelection(item);
			    });
			    
			    util.Control.redraw(app, "grpSearch");
			}

